package matteroverdrive.quest;

import matteroverdrive.item.ContractItem;import matteroverdrive.network.ModNetwork;import matteroverdrive.registry.ModSounds;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.ServerPlayer;import net.minecraft.sounds.SoundSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import java.util.List;
/** Scientist campaign front-end for the canonical research progression. */
public final class ScientistStoryQuestFlow {
 public static final String STORY_INDEX="MatterOverdriveScientistStoryIndex",STORY_DONE="MatterOverdriveScientistStoryDone",RESEARCH_RANK="MatterOverdriveScientistResearchRank";private ScientistStoryQuestFlow(){}
 public static boolean handle(ServerPlayer p){CompoundTag d=data(p);if(d.getBoolean(STORY_DONE)){showNextResearch(p,d);return true;}int i=normalize(p,d);ItemStack active=find(p,i);if(!active.isEmpty()){if(!ContractItem.complete(active)){dialogueProgress(p,active,d);return true;}redeem(p,active,d);return true;}if(i>=LegacyStoryContracts.QUEST_IDS.length){finishProgramme(p,d);return true;}String id=LegacyStoryContracts.QUEST_IDS[i];ItemStack q=LegacyStoryContracts.create(id,p.getRandom());if(q.isEmpty())return false;give(p,q);save(p,d);p.level().playSound(null,p.blockPosition(),ModSounds.get("gui.quest_started").get(),SoundSource.NEUTRAL,1,1);ModNetwork.openDialogue(p,scientist(i),ContractItem.title(q),List.of(intro(i),story(id),objective(q),"Research clearance: "+rank(d.getInt(RESEARCH_RANK)),"Programme: "+ResearchProgression.status(p),"Keep the contract with you. Return when the work is complete."));return true;}
 public static String status(ServerPlayer p){CompoundTag d=data(p);if(d.getBoolean(STORY_DONE))return ResearchProgression.status(p);int i=Math.min(Math.max(0,d.getInt(STORY_INDEX)),LegacyStoryContracts.QUEST_IDS.length);if(i>=LegacyStoryContracts.QUEST_IDS.length)return ResearchProgression.status(p);ItemStack a=find(p,i);return a.isEmpty()?"Next assignment: "+display(LegacyStoryContracts.QUEST_IDS[i]):ContractItem.title(a)+" - "+objective(a)+" ("+ContractItem.progress(a)+"/"+ContractItem.goal(a)+")";}
 private static void finishProgramme(ServerPlayer p,CompoundTag d){d.putBoolean(STORY_DONE,true);d.putInt(RESEARCH_RANK,4);save(p,d);ResearchProgression.unlock(p,ResearchProgression.Stage.MATTER_TECHNOLOGY);showNextResearch(p,d);}
 private static void showNextResearch(ServerPlayer p,CompoundTag d){ResearchProgression.unlock(p,ResearchProgression.Stage.MATTER_TECHNOLOGY);ModNetwork.openDialogue(p,"Dr. Voss - Systems Research","Matter Technology Programme",List.of("The introductory programme is complete. Now we stop repairing old research and start building our own.","ACTIVE RESEARCH: Matter Technology","First principles: measure matter, decompose it, store it safely, then reproduce a known pattern.","Recommended equipment: Matter Scanner, Decomposer, Matter Container, Pattern Storage and Replicator.","Once your laboratory can turn ordinary resources into a controlled matter supply, automation becomes worthwhile."));}
 private static void dialogueProgress(ServerPlayer p,ItemStack a,CompoundTag d){int i=Math.max(0,index(ContractItem.contractId(a)));ModNetwork.openDialogue(p,scientist(i),ContractItem.title(a),List.of(progress(i),story(ContractItem.contractId(a)),objective(a),"Progress: "+ContractItem.progress(a)+" / "+ContractItem.goal(a),"Research clearance: "+rank(d.getInt(RESEARCH_RANK))));}
 private static void redeem(ServerPlayer p,ItemStack c,CompoundTag d){String id=ContractItem.contractId(c);int ci=index(id);if(ci<0)return;for(ItemStack r:ContractItem.rewardItems(c))give(p,r.copy());for(ItemStack r:LegacyStoryContracts.specialRewards(c))give(p,r.copy());if(ContractItem.xp(c)>0)p.giveExperiencePoints(ContractItem.xp(c));LegacyStoryContracts.applyWorldRewards(p,c);remove(p,c);cleanup(p,ci);int next=Math.max(Math.max(0,d.getInt(STORY_INDEX)),ci+1);d.putInt(STORY_INDEX,next);d.putInt(RESEARCH_RANK,Math.max(d.getInt(RESEARCH_RANK),researchRank(next)));if(next>=LegacyStoryContracts.QUEST_IDS.length)d.putBoolean(STORY_DONE,true);save(p,d);p.level().playSound(null,p.blockPosition(),ModSounds.get("gui.quest_complete").get(),SoundSource.NEUTRAL,1,1);if(next>=LegacyStoryContracts.QUEST_IDS.length){ResearchProgression.unlock(p,ResearchProgression.Stage.MATTER_TECHNOLOGY);ModNetwork.openDialogue(p,"Dr. Voss - Systems Research","Research Programme Complete",List.of(done(id),"Independent researcher clearance granted.","NEW PROGRAMME UNLOCKED: Matter Technology","Measure matter. Decompose it. Store it. Replicate it. Then return when the laboratory is ready for automation."));}else ModNetwork.openDialogue(p,scientist(ci),ContractItem.title(c)+" Complete",List.of(done(id),unlock(next),"Research clearance: "+rank(d.getInt(RESEARCH_RANK)),"Next assignment: "+display(LegacyStoryContracts.QUEST_IDS[next])+"."));}
 private static int researchRank(int n){return n>=6?4:n>=4?3:n>=2?2:n>=1?1:0;}private static String rank(int r){return switch(Math.max(0,Math.min(4,r))){case 1->"FIELD ASSISTANT";case 2->"RESEARCH OPERATOR";case 3->"SYSTEMS SPECIALIST";case 4->"INDEPENDENT RESEARCHER";default->"PROBATIONARY SUBJECT";};}
 private static String scientist(int i){return switch(i){case 0,1->"Dr. Voss - Systems Research";case 2->"Dr. Sato - Matter Biology";case 3,4->"Dr. Kessler - Applied Logistics";case 5->"Dr. Hale - Energy Systems";default->"Mad Scientist";};}private static String intro(int i){return switch(i){case 0->"Voss sent for you. Surviving conversion apparently qualifies you to repair everyone else's mistakes.";case 1->"The relay has a voice again. Now find out whether it has anything useful to say.";case 2->"Sato wants matter-exposed crop samples.";case 3->"Kessler has lost a supply route and this has become your problem.";case 4->"The agreement was only the first authentication layer.";case 5->"Hale refuses further field work until you can power your own laboratory.";default->"There is another assignment.";};}private static String progress(int i){return switch(i){case 0->"The relay is still dead.";case 1->"No useful signal yet.";case 2->"Sato is still waiting for crop scans.";case 3->"The supply chain remains broken.";case 4->"The authentication sequence is incomplete.";case 5->"Independent power first. Fusion research later.";default->"The assignment remains incomplete.";};}private static String unlock(int i){return switch(i){case 1->"Relay diagnostics added to your field remit.";case 2->"Matter analysis clearance granted.";case 3->"Logistics clearance granted.";case 4->"Network authentication clearance granted.";case 5->"Energy systems clearance granted.";default->"Independent research clearance granted.";};}
 private static String story(String id){return switch(id){case"crash_landing"->"Rebuild the damaged research relay hardware before its data decays.";case"we_must_know"->"Place the field coil so we can hear the relay report.";case"gmo"->"Scan agricultural samples exposed to matter technology.";case"trade_route"->"Follow the agreement trail, inspect the crate, and speak to a scientist.";case"stem_bolts"->"Use the agreement copy to complete the authentication sequence.";case"to_the_power_of"->"Prove you can establish independent generation.";default->"There is work to do.";};}private static String done(String id){return switch(id){case"crash_landing"->"The relay survived.";case"we_must_know"->"The signal is coherent. Now we investigate it.";case"gmo"->"Useful samples. Disturbing, but useful.";case"trade_route"->"The route is open again.";case"stem_bolts"->"Authentication accepted.";case"to_the_power_of"->"Independent power confirmed.";default->"Experiment complete.";};}
 private static int normalize(ServerPlayer p,CompoundTag d){int stored=Math.max(0,d.getInt(STORY_INDEX)),furthest=-1;for(ItemStack s:p.getInventory().items)if(s.getItem() instanceof ContractItem)furthest=Math.max(furthest,index(ContractItem.contractId(s)));int n=Math.min(Math.max(stored,furthest),LegacyStoryContracts.QUEST_IDS.length);if(n!=stored){d.putInt(STORY_INDEX,n);save(p,d);}return n;}private static ItemStack find(ServerPlayer p,int wanted){ItemStack f=ItemStack.EMPTY;int fi=-1;for(ItemStack s:p.getInventory().items){if(!(s.getItem() instanceof ContractItem))continue;int i=index(ContractItem.contractId(s));if(i<0)continue;if(i==wanted)return s;if(i>fi){f=s;fi=i;}}return f;}private static int index(String id){if(id==null)return-1;for(int i=0;i<LegacyStoryContracts.QUEST_IDS.length;i++)if(LegacyStoryContracts.QUEST_IDS[i].equals(id))return i;return-1;}private static void remove(ServerPlayer p,ItemStack t){for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i)==t){p.getInventory().setItem(i,ItemStack.EMPTY);return;}}private static void cleanup(ServerPlayer p,int through){for(int i=0;i<p.getInventory().getContainerSize();i++){ItemStack s=p.getInventory().getItem(i);if(s.getItem() instanceof ContractItem&&index(ContractItem.contractId(s))>=0&&index(ContractItem.contractId(s))<=through)p.getInventory().setItem(i,ItemStack.EMPTY);}}
 private static CompoundTag data(ServerPlayer p){return p.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG);}private static void save(ServerPlayer p,CompoundTag d){p.getPersistentData().put(Player.PERSISTED_NBT_TAG,d);p.getInventory().setChanged();}private static void give(ServerPlayer p,ItemStack s){if(!p.getInventory().add(s))p.drop(s,false);}private static String objective(ItemStack s){String st=ContractStageSupport.stageLabel(s);return st.isBlank()?ContractItem.objectiveText(s):st+": "+ContractItem.objectiveText(s);}private static String display(String id){ItemStack s=LegacyStoryContracts.create(id,net.minecraft.util.RandomSource.create(0));return s.isEmpty()?id:ContractItem.title(s);}
}
